import logging
import os
from typing import Dict, List, Optional

from config import CORPUS_DIR

_log = logging.getLogger(__name__)

LIBFUZZER_TEMPLATE = '''#include <stdint.h>
#include <stddef.h>
#include <string.h>

// Fuzz target: {target_func}
// Generated by BinMind

// 前向声明: 实际定义由目标二进制提供, 签名按参数数量推导
{forward_decl}

#ifdef __cplusplus
extern "C"
#endif
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {{
    if (size < {min_size}) return 0;

    // 将 fuzzer 输入字节通过 memcpy 映射到函数参数
    {param_prep}

    {call_target}

    return 0;
}}
'''


def generate_libfuzzer_harness(func_name: str, param_count: int = 1,
                               min_input_size: int = 16) -> str:
    params = []
    call_args = []

    for i in range(param_count):
        param_name = f'p{i}'
        offset = i * 4
        params.append(
            f'    int {param_name} = 0;\n'
            f'    memcpy(&{param_name}, data + {offset}, sizeof(int));')
        call_args.append(param_name)

    prep = '\n'.join(params) if params else '    (void)data;'
    call = f'    {func_name}({", ".join(call_args)});' if call_args \
        else f'    {func_name}();'

    # 前向声明: 按参数类型推导签名, 使 harness 可独立编译
    decl_params = ', '.join(f'int {a}' for a in call_args) if call_args else 'void'
    forward_decl = f'extern "C" void {func_name}({decl_params});'

    return LIBFUZZER_TEMPLATE.format(
        target_func=func_name,
        min_size=min_input_size,
        param_prep=prep,
        call_target=call,
        forward_decl=forward_decl,
    )


def setup_fuzzing_workspace(binary_path: str) -> Dict:
    binary_dir = os.path.dirname(os.path.abspath(binary_path))
    binary_name = os.path.splitext(os.path.basename(binary_path))[0]
    workspace = os.path.join(CORPUS_DIR, binary_name)

    os.makedirs(workspace, exist_ok=True)

    # write a tiny seed corpus
    seed_path = os.path.join(workspace, 'seed.bin')
    with open(seed_path, 'wb') as f:
        f.write(b'\x00' * 64)
        f.write(b'\xff' * 64)
        f.write(b'AAAA\x00')
        f.write(b'%s%s%s%s')

    makefile = os.path.join(workspace, 'Makefile')
    with open(makefile, 'w', encoding='utf-8') as f:
        f.write(f'''# Auto-generated fuzzing Makefile for {binary_name}
CXX ?= clang++
CXXFLAGS += -g -O1 -fsanitize=fuzzer,address

harness: harness.cpp
\t$(CXX) $(CXXFLAGS) -o harness harness.cpp -L{binary_dir} -l{binary_name}

run: harness
\t./harness -max_total_time=300 {workspace}/

clean:
\trm -f harness *.o
''')

    # 生成可编译的最小 harness.cpp 框架, 调用方按需替换 target_func
    harness_path = os.path.join(workspace, 'harness.cpp')
    harness_src = generate_libfuzzer_harness('target_function', param_count=1)
    with open(harness_path, 'w', encoding='utf-8') as f:
        f.write(harness_src)

    return {'workspace': workspace, 'seed': seed_path,
            'makefile': makefile, 'harness': harness_path}
